class stringx
{
  char *chars;
  void *my_buf;
public:
  stringx();
  stringx(const stringx &);
  stringx(const char *, int = -1);
  ~stringx();
  const char *c_str() const { return chars; }
  void append(const stringx &);
};

inline stringx operator+(const stringx &a, const stringx &b)
{
  stringx result(a);
  result.append(b);
  return result;
}

class entity
{
  char padding[112];
public:
  stringx fileName;
  void kill_anim(int);
  void unload_anim(const stringx &) const;
};

class entity_maker
{
public:
  void destroy_entity(entity *);
};

extern entity_maker *g_entity_maker;
void nglReleaseMeshFile(const char *);

class FEEntityManager
{
public:
  enum
  {
    SA_IDLE,
    SA_SPECIAL_OCC,
    SA_OCC_1,
    SA_OCC_2
  };

  entity *surfer_ent;
  char padding[20];
  int current_surfer_index;
  char padding2[620];
  bool surfer_loaded;

  stringx makeString(int surfer, int type);
  bool UnloadCurrentSurfer();
};

#define NULL 0
#define ANIM_PRIMARY 0

bool FEEntityManager::UnloadCurrentSurfer()
{
  if (surfer_ent)
  {
	  surfer_ent->kill_anim(ANIM_PRIMARY);
	  surfer_ent->unload_anim(makeString(current_surfer_index, SA_IDLE));
	  surfer_ent->unload_anim(makeString(current_surfer_index, SA_SPECIAL_OCC));
	  surfer_ent->unload_anim(makeString(current_surfer_index, SA_OCC_1));
	  surfer_ent->unload_anim(makeString(current_surfer_index, SA_OCC_2));
		nglReleaseMeshFile(((entity *)surfer_ent)->fileName.c_str());
		nglReleaseMeshFile((((entity *)surfer_ent)->fileName + stringx("_lo")).c_str());
		surfer_ent->kill_anim(ANIM_PRIMARY);
		g_entity_maker->destroy_entity(surfer_ent);
    surfer_ent = NULL;
    surfer_loaded = false;
    return true;
  }
  surfer_loaded = false;
  return false;
}
